CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, permissions VARCHAR(2000) NOT NULL DEFAULT '{}');
CREATE TABLE clients (id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL, email VARCHAR(255), plate VARCHAR(20), vehicle VARCHAR(255));
CREATE TABLE stock_items (id UUID PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, quantity DOUBLE PRECISION NOT NULL, reorder_point DOUBLE PRECISION NOT NULL, unit VARCHAR(30) NOT NULL);
CREATE TABLE service_orders (id UUID PRIMARY KEY, number VARCHAR(50) NOT NULL UNIQUE, client_id UUID NOT NULL REFERENCES clients(id), plate VARCHAR(20) NOT NULL, vehicle VARCHAR(255) NOT NULL, problem VARCHAR(2000) NOT NULL, stage VARCHAR(50) NOT NULL, value DOUBLE PRECISION NOT NULL, approved BOOLEAN NOT NULL, reserved BOOLEAN NOT NULL, progress INTEGER NOT NULL, days INTEGER NOT NULL, photos INTEGER NOT NULL, owner_initials VARCHAR(10) NOT NULL, checklist VARCHAR(1000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE stock_movements (id UUID PRIMARY KEY, item_id UUID NOT NULL REFERENCES stock_items(id), type VARCHAR(30) NOT NULL, quantity DOUBLE PRECISION NOT NULL, reason VARCHAR(1000), created_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by UUID REFERENCES users(id));
CREATE TABLE audit_logs (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), action VARCHAR(255) NOT NULL, target VARCHAR(255), detail VARCHAR(2000), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE notifications (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), title VARCHAR(255), message VARCHAR(2000), level VARCHAR(50), read BOOLEAN NOT NULL DEFAULT FALSE, target_view VARCHAR(100), target_order_id UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_orders_stage ON service_orders(stage); CREATE INDEX idx_orders_client ON service_orders(client_id); CREATE INDEX idx_movements_item ON stock_movements(item_id); CREATE INDEX idx_audit_created ON audit_logs(created_at); CREATE INDEX idx_notifications_user ON notifications(user_id);
